1	package zkcircuit
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// These tests pin the circuit-name identity rule: a name is the version's
12	// identity, so it must keep one exact value across submit, save and read.
13	//
14	// On the write path a name that is not complete, valid UTF-8 (a lone
15	// continuation byte, a truncated multi-byte character, an overlong form) is
16	// refused as ErrInvalidArgument before anything is committed — encoding/json
17	// would otherwise silently rewrite those bytes to U+FFFD at save time and
18	// the circuit would be stored under a different name than the caller asked
19	// for.
20	//
21	// On the read path a committed record whose raw name token carries invalid
22	// UTF-8 bytes, or \uXXXX escapes forming an unpaired surrogate, is data
23	// corruption: the whole directory read fails with ErrDataCorrupt naming the
24	// record and the name field, no partial results are returned, and the file
25	// stays byte-for-byte in place. Legal Chinese, emoji, an actually committed
26	// "�", a legal surrogate pair and the literal six characters \uD800 are all
27	// ordinary names and keep their exact value.
28	
29	// rawEnvelope builds a complete committed envelope around one circuit record
30	// whose name is the given raw JSON token (already quoted/escaped by the
31	// caller), plus optionally a second, always-legal circuit.
32	func rawEnvelope(nameJSON string, withSecond bool) []byte {
33		var b strings.Builder
34		b.WriteString(`{"format":1,"circuits":[`)
35		if withSecond {
36			b.WriteString(`{"name":"ok","version":1,"constraints":1,"public_inputs":0,"private_inputs":0,"frozen":false,"description":""},`)
37		}
38		b.WriteString(`{"name":`)
39		b.WriteString(nameJSON)
40		b.WriteString(`,"version":1,"constraints":1,"public_inputs":0,"private_inputs":0,"frozen":false,"description":""}],"setups":[],"jobs":[]}`)
41		return []byte(b.String())
42	}
43	
44	// plantRawEnvelope plants raw as the committed data.json of a fresh directory.
45	func plantRawEnvelope(t *testing.T, raw []byte) string {
46		t.Helper()
47		dir := filepath.Join(t.TempDir(), "bench")
48		if err := os.MkdirAll(dir, 0o755); err != nil {
