		// it, and the record is rejected at this point — before this second
		// occurrence's value is decoded — matching the old envelope scan. The
		// key may be any spelling here (an unknown field repeated is still a
		// duplicate to the scan tier); the typed decode's unknown-field gate
		// is what distinguishes the allowed spellings afterwards.
		if seen[key] {
			return nil, corruptf("%s contains duplicate field %q", positional, key)
		}
		seen[key] = true
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, corruptf("%s is not valid JSON: %v", positional, err)
		}
		r.members = append(r.members, circuitMember{key: key, value: value})
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
		return nil, corruptf("%s is not valid JSON", positional)
	}
	return r, nil
}

// scanCircuitArray consumes one "circuits" value positioned at its opening
// bracket and reads every record through the shared per-record engine, which
// names each structural or duplicate finding before the scan moves on. It is
// the directory-wide pre-check counterpart of decodeCircuit and exists so a
// structural problem inside one circuit is attributed to that record by its
// 1-based position rather than to an opaque "circuits" element index. A null
// array stays the pre-existing "no records" reading.
func scanCircuitArray(dec *json.Decoder) error {
	tok, err := dec.Token()
	if err != nil {
		return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
	}
	if tok == nil { // null: json.Unmarshal would produce no records
		return nil
	}
	if tok != json.Delim('[') {
		return corruptf("data file envelope field \"circuits\" must be an array")
	}
	index := 0
	for dec.More() {
		index++
		if _, err := readCircuitRecord(dec, fmt.Sprintf("circuit record #%d", index)); err != nil {
			return err
		}
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
		return corruptf("data file envelope field \"circuits\" is not valid JSON")
	}
	return nil
}

