func TestProbe(t *testing.T) {
	w, _ := os.Create("/tmp/probe.out")
	defer w.Close()
	recs := craftRecords()
	keys := make([]string, 0, len(recs))
	for k := range recs {
		keys = append(keys, k)
	}
	// stable order: just sort
	for i := 0; i < len(keys); i++ {
		for j := i + 1; j < len(keys); j++ {
			if keys[j] < keys[i] {
				keys[i], keys[j] = keys[j], keys[i]
			}
		}
	}
	for _, k := range keys {
		rec := recs[k]
		// single-record decode
		var pc persistCircuit
		err := json.Unmarshal([]byte(rec), &pc)
		if err != nil {
			fmt.Fprintf(w, "REC %-28s ERR %s\n", k, oneLine(err))
		} else {
			fmt.Fprintf(w, "REC %-28s OK  name=%q frozen=%v def=%v\n", k, pc.Name, pc.Frozen, pc.Definition != nil)
		}
		// envelope decode (full data pre-check + typed decode), one record
		env1 := `{"format":1,"circuits":[` + rec + `],"setups":[],"jobs":[]}`
		var e envelope
		eerr := json.Unmarshal([]byte(env1), &e)
		if eerr != nil {
			fmt.Fprintf(w, "ENV1 %-28s ERR %s\n", k, oneLine(eerr))
		} else {
			fmt.Fprintf(w, "ENV1 %-28s OK  n=%d\n", k, len(e.Circuits))
		}
	}
	// Multi-record: first record good, second carrying a damage; and reversed.
	badKinds := []string{"dupname", "null", "missing-frozen", "num-frozen", "unknown-first", "name-surrogate", "dupname-same"}
	good := recs["good"]
	for _, bk := range badKinds {
		for _, order := range []string{"good-bad", "bad-good"} {
			var arr string
			if order == "good-bad" {
				arr = good + "," + recs[bk]
			} else {
				arr = recs[bk] + "," + good
			}
			env := `{"format":1,"circuits":[` + arr + `],"setups":[],"jobs":[]}`
			var e envelope
			eerr := json.Unmarshal([]byte(env), &e)
			tag := bk + "/" + order
			if eerr != nil {
				fmt.Fprintf(w, "ENVM %-28s ERR %s\n", tag, oneLine(eerr))
			} else {
				fmt.Fprintf(w, "ENVM %-28s OK  n=%d\n", tag, len(e.Circuits))
			}
		}
	}
}

func oneLine(err error) string {
	s := err.Error()
	s = strings.ReplaceAll(s, "\n", " ")
	return s
